/**
 * Shared email-safe visual shell for USD transactional and competition mail.
 * All supplied text and href fields are escaped here. bodyHtml / logoHtml are
 * generated by trusted renderers which escape CMS/user substitutions upstream.
 *
 * Tables and inline styling deliberately support Gmail, Yandex, Apple Mail
 * and Outlook; no external fonts, scripts or images are required to read mail.
 */
function escapeEmail(value: string): string {
  return String(value).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[ch] ?? ch);
}

export type UsdMailShellOptions = {
  heading: string;
  bodyHtml: string;
  actionUrl: string;
  actionLabel: string;
  frontendUrl: string;
  footerHtml: string;
  eyebrow?: string;
  preheader?: string;
  logoHtml?: string;
  footerLinkHref?: string;
  footerLinkText?: string;
};

export function renderUsdMailShell(options: UsdMailShellOptions): string {
  const heading = escapeEmail(options.heading);
  const cta = escapeEmail(options.actionLabel);
  const actionUrl = escapeEmail(options.actionUrl);
  const frontend = escapeEmail(options.frontendUrl);
  const footerUrl = escapeEmail(options.footerLinkHref ?? options.frontendUrl);
  const footerLink = escapeEmail(options.footerLinkText ?? 'Открыть сайт USD');
  const eyebrow = escapeEmail(options.eyebrow ?? 'СООБЩЕНИЕ СИСТЕМЫ USD');
  const preheader = escapeEmail(options.preheader ?? options.heading);
  const wordmark = '<span style="font-family:Arial,Helvetica,sans-serif;font-size:34px;line-height:1;font-weight:900;letter-spacing:-2px;color:#ffffff">USD<span style="color:#ed2638">.</span></span>';
  const logo = options.logoHtml ?? wordmark;

  return `<!doctype html>
<html lang="ru"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<title>USD — ${heading}</title>
<style>
@media only screen and (max-width:620px){
  .usd-email-outer{padding:12px 8px!important}
  .usd-email-inner{width:100%!important}
  .usd-email-head{padding:25px 22px!important}
  .usd-email-main{padding:30px 22px 26px!important}
  .usd-email-title{font-size:27px!important;line-height:1.14!important}
  .usd-email-foot{padding:20px 22px!important}
  .usd-email-button{display:block!important;text-align:center!important}
}
</style></head>
<body style="margin:0;padding:0;background-color:#ebedf0;color:#17191d;font-family:Arial,Helvetica,sans-serif;-webkit-text-size-adjust:100%">
<div style="display:none!important;visibility:hidden;opacity:0;height:0;width:0;overflow:hidden;color:transparent;mso-hide:all">${preheader}</div>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse;background-color:#ebedf0"><tr><td align="center" class="usd-email-outer" style="padding:38px 16px 45px">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" class="usd-email-inner" width="600" style="width:600px;max-width:100%;border-collapse:separate;border-spacing:0;background:#ffffff;border:1px solid #dadde1;border-radius:18px;overflow:hidden">
<tr><td class="usd-email-head" style="padding:30px 36px 28px;background-color:#0b0b0d;border-bottom:4px solid #ed2638;color:#ffffff">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td align="left" valign="middle">${logo}</td><td align="right" valign="middle" style="color:#9ca0a8;font-size:10px;font-weight:700;letter-spacing:1.4px;line-height:1.5;max-width:118px">ULTIMATE SOUND DESTRUCTION</td></tr></table>
</td></tr>
<tr><td class="usd-email-main" style="padding:42px 42px 34px;background:#ffffff">
<p style="margin:0 0 13px;color:#c71c39;font-size:10px;line-height:1.5;font-weight:800;letter-spacing:2px;text-transform:uppercase">${eyebrow}</p>
<h1 class="usd-email-title" style="margin:0 0 22px;color:#15171b;font-size:32px;line-height:1.14;font-family:Arial,Helvetica,sans-serif;letter-spacing:-.8px;font-weight:900">${heading}</h1>
<div style="margin:0 0 28px;color:#4f5660;font-size:15px;line-height:1.72;overflow-wrap:anywhere">${options.bodyHtml}</div>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td style="padding:0 0 28px">
<a class="usd-email-button" href="${actionUrl}" style="display:inline-block;padding:16px 25px;background-color:#d91f3a;border:1px solid #bf1932;border-radius:10px;color:#ffffff;text-decoration:none;font-size:14px;font-weight:800;line-height:1.4;text-align:center">${cta} &nbsp; &#8599;</a>
</td></tr></table>
<div style="margin:0;padding:18px 20px;background:#f5f6f8;border-left:3px solid #ed2638;border-radius:0 10px 10px 0;color:#626a74;font-size:12px;line-height:1.7">${options.footerHtml}</div>
</td></tr>
<tr><td class="usd-email-foot" style="padding:22px 42px;background:#0f1115;border-top:1px solid #2c3038;color:#a8adb6">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>
<td valign="middle" style="font-size:11px;line-height:1.6;color:#a8adb6"><strong style="color:#ffffff;letter-spacing:1px">USD</strong><br>Звук. Мощность. Характер.</td>
<td valign="middle" align="right"><a href="${footerUrl}" style="font-size:11px;line-height:1.5;font-weight:700;color:#f5f5f6;text-decoration:underline;text-decoration-color:#ed2638">${footerLink}</a></td>
</tr></table>
</td></tr>
</table>
<p style="margin:19px 0 0;font-size:11px;line-height:1.7;color:#767c84;text-align:center">USD · <a href="${frontend}" style="color:#686e78;text-decoration:underline">Официальный сайт соревнований</a></p>
</td></tr></table></body></html>`;
}
